using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _service;

    public NotificationServiceTests()
    {
        _service = new NotificationService();
        // Drain the static queue to ensure test isolation
        while (_service.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain queue after each test
        while (_service.ReceiveNotification() != null) { }
        _service.Dispose();
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_Create()
    {
        _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
        Assert.True(notification.CreatedAt <= DateTime.Now);
        Assert.True(notification.CreatedAt > DateTime.Now.AddSeconds(-5));
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_Update()
    {
        _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
        Assert.Equal("UPDATE", notification.Operation);
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_Delete()
    {
        _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        Assert.Equal("DELETE", notification.Operation);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Instructor", "42", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Instructor (ID: 42) has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Student", "7", null, EntityOperation.UPDATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 7) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
    {
        _service.SendNotification("Student", "7", "  ", EntityOperation.DELETE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student (ID: 7) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        var notification = _service.ReceiveNotification();
        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_DequeuesInOrder()
    {
        _service.SendNotification("A", "1", "First", EntityOperation.CREATE, "User");
        _service.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "User");
        _service.SendNotification("C", "3", "Third", EntityOperation.DELETE, "User");

        var first = _service.ReceiveNotification();
        var second = _service.ReceiveNotification();
        var third = _service.ReceiveNotification();
        var fourth = _service.ReceiveNotification();

        Assert.Equal("A", first.EntityType);
        Assert.Equal("B", second.EntityType);
        Assert.Equal("C", third.EntityType);
        Assert.Null(fourth);
    }

    [Fact]
    public void SendNotification_MultipleMessages_AllEnqueued()
    {
        for (int i = 0; i < 10; i++)
        {
            _service.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE, "User");
        }

        int count = 0;
        while (_service.ReceiveNotification() != null) count++;

        Assert.Equal(10, count);
    }

    [Fact]
    public void SendNotification_QueueCapEnforced()
    {
        // Enqueue more than max (500)
        for (int i = 0; i < 510; i++)
        {
            _service.SendNotification("Entity", i.ToString(), $"Name{i}", EntityOperation.CREATE, "User");
        }

        int count = 0;
        while (_service.ReceiveNotification() != null) count++;

        Assert.True(count <= 500, $"Queue should be capped at 500, got {count}");
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op, just verify it doesn't throw
        var ex = Record.Exception(() => _service.MarkAsRead(1));
        Assert.Null(ex);
    }

    [Fact]
    public void MarkAsRead_WithAnyId_DoesNotThrow()
    {
        var ex = Record.Exception(() => _service.MarkAsRead(999));
        Assert.Null(ex);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_4ParamOverload_SetsOperationCorrectly()
    {
        _service.SendNotification("Student", "1", EntityOperation.DELETE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal("Student (ID: 1) has been deleted", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _service.SendNotification("Course", "1", "Math", EntityOperation.CREATE, "Admin");

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNow()
    {
        var before = DateTime.Now.AddMilliseconds(-100);
        _service.SendNotification("Course", "1", "Math", EntityOperation.CREATE, "Admin");
        var after = DateTime.Now.AddMilliseconds(100);

        var notification = _service.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }
}

