using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextHelper.CreateInMemoryContext();
        _controller = new StudentsController(_context);
        // Set up TempData for controller
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), 
            new Mock<ITempDataProvider>().Object);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Student CreateStudent(string lastName = "Doe", string firstName = "John", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            LastName = lastName,
            FirstMidName = firstName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2024, 9, 1)
        };
        _context.Students.Add(student);
        _context.SaveChanges();
        return student;
    }

    private void SeedMultipleStudents()
    {
        _context.Students.AddRange(
            new Student { LastName = "Alexander", FirstMidName = "Carson", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { LastName = "Alonso", FirstMidName = "Meredith", EnrollmentDate = new DateTime(2019, 9, 1) },
            new Student { LastName = "Barzdukas", FirstMidName = "Gytis", EnrollmentDate = new DateTime(2018, 9, 1) },
            new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { LastName = "Justice", FirstMidName = "Peggy", EnrollmentDate = new DateTime(2021, 9, 1) }
        );
        _context.SaveChanges();
    }

    // === Index Tests ===

    [Fact]
    public void Index_ReturnsViewResult_WithPaginatedList()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(5, model.Count);
    }

    [Fact]
    public void Index_DefaultSort_OrdersByLastNameAscending()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Barzdukas", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_OrdersByLastNameDescending()
    {
        SeedMultipleStudents();
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Li", model[0].LastName);
        Assert.Equal("Justice", model[1].LastName);
    }

    [Fact]
    public void Index_DateSort_OrdersByEnrollmentDateAscending()
    {
        SeedMultipleStudents();
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Barzdukas", model[0].LastName); // 2018
    }

    [Fact]
    public void Index_DateDescSort_OrdersByEnrollmentDateDescending()
    {
        SeedMultipleStudents();
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Justice", model[0].LastName); // 2021
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByLastName()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, null, "Li", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Li", model[0].LastName);
    }

    [Fact]
    public void Index_SearchString_FiltersStudentsByFirstName()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, null, "Carson", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Carson", model[0].FirstMidName);
    }

    [Fact]
    public void Index_SearchString_ResetsPageTo1()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, null, "Al", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_CurrentFilter_UsedWhenSearchStringIsNull()
    {
        SeedMultipleStudents();
        var result = _controller.Index(null, "Li", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
    }

    [Fact]
    public void Index_SetsViewBagCurrentSort()
    {
        SeedMultipleStudents();
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        Assert.Equal("name_desc", _controller.ViewBag.CurrentSort);
    }

    [Fact]
    public void Index_SetsViewBagNameSortParm()
    {
        // When sortOrder is empty, NameSortParm should be "name_desc"
        _controller.Index(null, null, null, null);
        Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);

        // When sortOrder is "name_desc", NameSortParm should be ""
        _controller.Index("name_desc", null, null, null);
        Assert.Equal("", _controller.ViewBag.NameSortParm);
    }

    [Fact]
    public void Index_SetsViewBagDateSortParm()
    {
        // When sortOrder is "Date", DateSortParm should be "date_desc"
        _controller.Index("Date", null, null, null);
        Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);

        // Otherwise, DateSortParm should be "Date"
        _controller.Index(null, null, null, null);
        Assert.Equal("Date", _controller.ViewBag.DateSortParm);
    }

    [Fact]
    public void Index_Pagination_Page2()
    {
        // Seed 15 students to have 2 pages with pageSize=10
        for (int i = 0; i < 15; i++)
        {
            _context.Students.Add(new Student
            {
                LastName = $"Student{i:D2}",
                FirstMidName = $"First{i}",
                EnrollmentDate = new DateTime(2024, 1, 1)
            });
        }
        _context.SaveChanges();

        var result = _controller.Index(null, null, null, 2) as ViewResult;
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);

        Assert.Equal(5, model.Count);
        Assert.Equal(2, model.PageIndex);
        Assert.True(model.HasPreviousPage);
        Assert.False(model.HasNextPage);
    }

    // === Details Tests ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Details(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
        Assert.Equal("Doe", model.LastName);
        Assert.Equal("John", model.FirstMidName);
    }

    // === Create GET Tests ===

    [Fact]
    public void Create_GET_ReturnsViewWithStudentWithTodaysDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, model.EnrollmentDate);
    }

    // === Create POST Tests ===

    [Fact]
    public void Create_POST_ValidStudent_RedirectsToIndex()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(2024, 9, 1)
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_POST_ValidStudent_SavesStudentToDatabase()
    {
        var student = new Student
        {
            LastName = "NewStudent",
            FirstMidName = "Test",
            EnrollmentDate = new DateTime(2024, 9, 1)
        };

        _controller.Create(student);

        var saved = _context.Students.FirstOrDefault(s => s.LastName == "NewStudent");
        Assert.NotNull(saved);
        Assert.Equal("Test", saved.FirstMidName);
        Assert.Equal(new DateTime(2024, 9, 1), saved.EnrollmentDate);
    }

    [Fact]
    public void Create_POST_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_POST_DateBelow1753_AddsModelError()
    {
        var student = new Student
        {
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = new DateTime(1752, 12, 31)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            EnrollmentDate = new DateTime(2024, 9, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.IsType<Student>(result.Model);
    }

    // === Edit GET Tests ===

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_NotFound_Returns404()
    {
        var result = _controller.Edit(9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Edit(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    // === Edit POST Tests ===

    [Fact]
    public void Edit_POST_ValidStudent_RedirectsToIndex()
    {
        var student = CreateStudent();
        // Detach so the edit won't conflict
        _context.Entry(student).State = EntityState.Detached;

        var editedStudent = new Student
        {
            ID = student.ID,
            LastName = "Updated",
            FirstMidName = "Name",
            EnrollmentDate = new DateTime(2024, 9, 1)
        };

        var result = _controller.Edit(editedStudent) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_POST_DefaultEnrollmentDate_AddsModelError()
    {
        var student = new Student
        {
            ID = 1,
            LastName = "Test",
            FirstMidName = "User",
            EnrollmentDate = default(DateTime)
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_POST_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var student = new Student
        {
            ID = 1,
            EnrollmentDate = new DateTime(2024, 9, 1)
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
    }

    // === Delete GET Tests ===

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_NotFound_Returns404()
    {
        var result = _controller.Delete(9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsViewWithStudent()
    {
        var student = CreateStudent();

        var result = _controller.Delete(student.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Student>(result.Model);
        Assert.Equal(student.ID, model.ID);
    }

    // === DeleteConfirmed Tests ===

    [Fact]
    public void DeleteConfirmed_RemovesStudent_RedirectsToIndex()
    {
        var student = CreateStudent();

        var result = _controller.DeleteConfirmed(student.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Students.Find(student.ID));
    }

    [Fact]
    public void DeleteConfirmed_StudentNotFound_RedirectsToIndex()
    {
        // Trying to delete a non-existent student should catch the exception and redirect
        var result = _controller.DeleteConfirmed(9999) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }
}

