using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Controllers;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestDbContextHelper.CreateInMemoryContext();
        _controller = new InstructorsController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    private Instructor CreateInstructor(string lastName = "Smith", string firstName = "Bob")
    {
        var instructor = new Instructor
        {
            LastName = lastName,
            FirstMidName = firstName,
            HireDate = new DateTime(2010, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();
        return instructor;
    }

    private Course CreateCourse(int id, string title = "Chemistry")
    {
        // Ensure department exists
        if (!_context.Departments.Any())
        {
            _context.Departments.Add(new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1)
            });
            _context.SaveChanges();
        }

        var course = new Course
        {
            CourseID = id,
            Title = title,
            Credits = 3,
            DepartmentID = 1,
            Enrollments = new List<Enrollment>()
        };
        _context.Courses.Add(course);
        _context.SaveChanges();
        return course;
    }

    // === Index Tests ===

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructorIndexData()
    {
        CreateInstructor();
        CreateInstructor("Jones", "Mary");

        var result = _controller.Index(null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.Equal(2, model.Instructors.Count());
    }

    [Fact]
    public void Index_WithInstructorId_SetsCourses()
    {
        var instructor = CreateInstructor();
        var course = CreateCourse(1050);
        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var result = _controller.Index(instructor.ID, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Courses);
        Assert.Single(model.Courses);
    }

    [Fact]
    public void Index_WithInstructorIdAndCourseId_SetsEnrollments()
    {
        var instructor = CreateInstructor();
        var course = CreateCourse(2050, "Physics");
        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = course.CourseID };
        _context.CourseAssignments.Add(ca);

        var student = new Student
        {
            LastName = "TestStudent",
            FirstMidName = "Test",
            EnrollmentDate = DateTime.Now
        };
        _context.Students.Add(student);
        _context.SaveChanges();

        var enrollment = new Enrollment
        {
            CourseID = course.CourseID,
            StudentID = student.ID,
            Grade = Grade.A
        };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var result = _controller.Index(instructor.ID, course.CourseID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<InstructorIndexData>(result.Model);
        Assert.NotNull(model.Enrollments);
        Assert.Single(model.Enrollments);
    }

    // === Details Tests ===

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Details_NotFound_Returns404()
    {
        var result = _controller.Details(9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateInstructor();

        var result = _controller.Details(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
        Assert.Equal("Smith", model.LastName);
    }

    // === Create GET Tests ===

    [Fact]
    public void Create_GET_ReturnsViewWithInstructor()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.Empty(model.CourseAssignments);
    }

    // === Create POST Tests ===

    [Fact]
    public void Create_POST_ValidInstructor_NoSelectedCourses_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            LastName = "NewInst",
            FirstMidName = "Test",
            HireDate = new DateTime(2024, 1, 1)
        };

        var result = _controller.Create(instructor, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Create_POST_ValidInstructor_SavesToDB()
    {
        var instructor = new Instructor
        {
            LastName = "Saved",
            FirstMidName = "Instructor",
            HireDate = new DateTime(2024, 1, 1)
        };

        _controller.Create(instructor, null);

        var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "Saved");
        Assert.NotNull(saved);
        Assert.Equal("Instructor", saved.FirstMidName);
    }

    [Fact]
    public void Create_POST_WithSelectedCourses_AddsCourseAssignments()
    {
        var course1 = CreateCourse(3000, "Course1");
        var course2 = CreateCourse(3001, "Course2");

        var instructor = new Instructor
        {
            LastName = "WithCourses",
            FirstMidName = "Inst",
            HireDate = new DateTime(2024, 1, 1)
        };

        var selectedCourses = new[] { course1.CourseID.ToString(), course2.CourseID.ToString() };
        _controller.Create(instructor, selectedCourses);

        var saved = _context.Instructors
            .Include(i => i.CourseAssignments)
            .FirstOrDefault(i => i.LastName == "WithCourses");
        Assert.NotNull(saved);
        Assert.Equal(2, saved.CourseAssignments.Count);
    }

    [Fact]
    public void Create_POST_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            HireDate = new DateTime(2024, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null) as ViewResult;

        Assert.NotNull(result);
    }

    // === Edit GET Tests ===

    [Fact]
    public void Edit_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_GET_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateInstructor();

        var result = _controller.Edit(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // === Delete GET Tests ===

    [Fact]
    public void Delete_GET_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);
        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal(400, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_GET_NotFound_Returns404()
    {
        var result = _controller.Delete(9999);
        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_GET_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = CreateInstructor();

        var result = _controller.Delete(instructor.ID) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<Instructor>(result.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // === DeleteConfirmed Tests ===

    [Fact]
    public void DeleteConfirmed_RemovesInstructor_RedirectsToIndex()
    {
        var instructor = CreateInstructor("ToDelete", "Inst");

        var result = _controller.DeleteConfirmed(instructor.ID) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Instructors.Find(instructor.ID));
    }

    [Fact]
    public void DeleteConfirmed_InstructorIsDepartmentAdmin_ClearsDepartmentInstructorID()
    {
        var instructor = CreateInstructor("Admin", "Dept");
        var dept = new Department
        {
            Name = "AdminDept",
            Budget = 100000m,
            StartDate = new DateTime(2020, 1, 1),
            InstructorID = instructor.ID
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        _controller.DeleteConfirmed(instructor.ID);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(updatedDept);
        Assert.Null(updatedDept.InstructorID);
    }
}

