namespace ContosoUniversity.Tests.Controllers;

public class HomeControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly HomeController _controller;

    public HomeControllerTests()
    {
        _context = TestDbContextHelper.CreateInMemoryContext();
        _controller = new HomeController(_context);
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void About_ReturnsViewResult_WithEnrollmentDateGroups()
    {
        // Seed some students
        _context.Students.AddRange(
            new Student { LastName = "A", FirstMidName = "B", EnrollmentDate = new DateTime(2024, 9, 1) },
            new Student { LastName = "C", FirstMidName = "D", EnrollmentDate = new DateTime(2024, 9, 1) },
            new Student { LastName = "E", FirstMidName = "F", EnrollmentDate = new DateTime(2023, 9, 1) }
        );
        _context.SaveChanges();

        var result = _controller.About() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Equal(2, model.Count);

        // The group with 2024-09-01 should have 2 students
        var group2024 = model.FirstOrDefault(g => g.EnrollmentDate == new DateTime(2024, 9, 1));
        Assert.NotNull(group2024);
        Assert.Equal(2, group2024.StudentCount);

        // The group with 2023-09-01 should have 1 student
        var group2023 = model.FirstOrDefault(g => g.EnrollmentDate == new DateTime(2023, 9, 1));
        Assert.NotNull(group2023);
        Assert.Equal(1, group2023.StudentCount);
    }

    [Fact]
    public void About_NoStudents_ReturnsEmptyList()
    {
        var result = _controller.About() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(result.Model);
        Assert.Empty(model);
    }

    [Fact]
    public void Contact_ReturnsViewResult()
    {
        var result = _controller.Contact() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("Your contact page.", _controller.ViewBag.Message);
    }

    [Fact]
    public void Error_ReturnsViewResult()
    {
        var result = _controller.Error();
        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void Unauthorized_ReturnsViewResult_WithMessage()
    {
        var result = _controller.Unauthorized() as ViewResult;

        Assert.NotNull(result);
        Assert.Equal("You don't have permission to access this resource.", _controller.ViewBag.Message);
    }
}

