using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests.Controllers;

/// <summary>
/// Additional tests for CoursesController focusing on edge cases and uncovered paths
/// </summary>
public class CoursesControllerAdditionalTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;
    private readonly string _tempDir;

    public CoursesControllerAdditionalTests()
    {
        _context = TestDbContextHelper.CreateInMemoryContext();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _tempDir = Path.Combine(Path.GetTempPath(), $"contoso_test_{Guid.NewGuid():N}");
        Directory.CreateDirectory(_tempDir);
        _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
        _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
        _mockLogger = new Mock<ILogger<CoursesController>>();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);

        // Seed department
        _context.Departments.Add(new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = new DateTime(2007, 9, 1)
        });
        _context.SaveChanges();
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        try { Directory.Delete(_tempDir, true); } catch { }
    }

    [Fact]
    public void Create_POST_ValidImageFile_SavesFileAndSetsPath()
    {
        var course = new Course { CourseID = 10000, Title = "FileTest", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("image.jpg");
        mockFile.Setup(f => f.Length).Returns(1024);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);

        var saved = _context.Courses.Find(10000);
        Assert.NotNull(saved);
        Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Create_POST_ZeroLengthFile_IgnoresFile()
    {
        var course = new Course { CourseID = 10001, Title = "EmptyFile", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("test.jpg");
        mockFile.Setup(f => f.Length).Returns(0);

        var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = _context.Courses.Find(10001);
        Assert.Null(saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Edit_POST_ValidImageFile_UpdatesPath()
    {
        var course = new Course { CourseID = 10002, Title = "EditFileTest", Credits = 3, DepartmentID = 1 };
        _context.Courses.Add(course);
        _context.SaveChanges();
        _context.Entry(course).State = EntityState.Detached;

        var editCourse = new Course { CourseID = 10002, Title = "EditFileTest", Credits = 3, DepartmentID = 1 };
        var mockFile = new Mock<IFormFile>();
        mockFile.Setup(f => f.FileName).Returns("updated.png");
        mockFile.Setup(f => f.Length).Returns(2048);
        mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Edit(editCourse, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
    }

    [Fact]
    public void Edit_POST_WithExistingImage_DeletesOldFile()
    {
        // Create a fake existing image file
        var uploadsDir = Path.Combine(_tempDir, "Uploads", "TeachingMaterials");
        Directory.CreateDirectory(uploadsDir);
        var oldFileName = "old_image.jpg";
        var oldFilePath = Path.Combine(uploadsDir, oldFileName);
        File.WriteAllText(oldFilePath, "fake image data");

        var course = new Course
        {
            CourseID = 10003,
            Title = "ReplaceImage",
            Credits = 3,
            DepartmentID = 1,
            TeachingMaterialImagePath = $"/Uploads/TeachingMaterials/{oldFileName}"
        };
